    const b = req.body || {}, email = lc(clean(b.email, 200)), gift = (h.gifts || []).find((x) => x.id === b.experienceId), qn = Math.max(0, Math.round(+b.people || 0)), gc = gift ? ((gift.tiers || []).filter((t) => qn >= t.qty).pop()?.cents || gift.cents) : 0, exp = (h.experiences || []).find((x) => x.id === b.experienceId) || (gift ? { id: gift.id, name: gift.name, price: gc ? `$${(gc / 100).toFixed(gc % 100 ? 2 : 0)} each` : "", lead: gift.lead || "" } : null); if (!EMAIL_OK(email)) return bad(res, "Add a work email so the host can reply.");
    const people = Math.max(0, Math.min(5000, Math.round(+b.people || 0))), msg = clean(b.message, 1500); if (gift && msg.length < 10) return bad(res, "Say a little about the occasion.");
    const dup = scopeStore(store, ws).list("inquiries").map((d) => d.data).find((x) => x.email === email && (x.experience?.id || "") === (exp?.id || "") && x.when === clean(b.when, 80) && x.company === clean(b.company, 120) && x.people === Math.max(0, Math.min(5000, Math.round(+b.people || 0))) && x.message === clean(b.message, 1500) && Date.now() - x.at < 30 * 60e3);
    if (dup) return res.json({ ok: true, id: dup.id, status: `${publicOrigin(req)}/booking/${dup.id}?t=${token(dup.id)}`, duplicate: true });
    const id = crypto.randomBytes(6).toString("hex"), held = !!b.hold && !!exp && C.openDatesOf(ws, (h.experiences || []).find((x) => x.id === exp.id) || {}).includes(String(b.date || "")), inq = { id, ...(b.series?.id ? { series: { id: clean(b.series.id, 20), n: Math.max(1, Math.min(52, +b.series.n || 1)), of: Math.max(1, Math.min(52, +b.series.of || 1)) } } : {}), time: /^\d{2}:\d{2}$/.test(String(b.time || "")) ? b.time : "", ...(held ? { holdUntil: Date.now() + 72 * 3600e3 } : {}), date: /^\d{4}-\d{2}-\d{2}$/.test(String(b.date || "")) ? b.date : "", kind: gift ? "gift" : "booking", ...(!gift && b.scope && typeof b.scope === "object" ? { scope: { deliverables: (Array.isArray(b.scope.deliverables) ? b.scope.deliverables : []).filter((k) => ["photos", "post", "stories", "reel", "product"].includes(k)).slice(0, 5), usage: USAGE_TIERS.some(([k]) => k === b.scope.usage) ? b.scope.usage : "organic30", raw: !!b.scope.raw, remote: Math.max(0, Math.min(5000, Math.round(+b.scope.remote || 0))) } } : {}), ...(gift ? { personalize: clean(b.personalize, 1200), sample: !!b.sample, shipTo: clean(b.shipTo, 40) } : {}), ...(Array.isArray(b.addOns) && b.addOns.length ? { addOns: b.addOns.slice(0, 5).map((a) => ({ handle: clean(a?.handle, 60), id: clean(a?.id, 20), t: clean(a?.t, 40), name: clean(a?.name, 120), est: clean(a?.est, 80) })) } : {}), ...(b.partOf ? { partOf: { id: clean(b.partOf.id, 20), name: clean(b.partOf.name, 120) } } : {}), ...(b.addOn ? { addOn: { handle: clean(b.addOn.handle, 60), id: clean(b.addOn.id, 20), t: clean(b.addOn.t, 40), name: clean(b.addOn.name, 120), est: clean(b.addOn.est, 80) } } : {}), ...(cleanCrm(b.crm, clean) ? { crm: cleanCrm(b.crm, clean) } : {}), ...(!gift && cleanAgency(b.agency, clean) ? { agency: cleanAgency(b.agency, clean) } : {}), ...(b.hold ? { holdAsked: true } : {}), status: "requested", name: clean(b.name, 80), company: clean(b.company, 120), email, message: msg, when: clean(b.when, 80), budget: clean(b.budget, 80), where: clean(b.where, 160), people, experience: exp ? { id: exp.id, name: exp.name, price: exp.price } : null, at: Date.now(), history: [{ at: Date.now(), by: "brand", what: "requested" }] };
    const xx0 = !gift && (h.experiences || []).find((x) => x.id === exp?.id); if (xx0) { const P = priceLines(xx0, people, inq.scope || {}); inq.estimate = { lines: P.lines, total: P.total, unpriced: P.unpriced, deposit: P.deposit }; }
